<?php declare(strict_types=1); namespace App\Application\Arena\Service; use App\Application\Arena\Mapper\ArenaRoomSummaryMapper; use App\Domain\Arena\Repository\DuelRepositoryInterface; final class ListArenaRoomsService { public function __construct(private readonly DuelRepositoryInterface $rooms,private readonly ArenaRoomSummaryMapper $mapper){} public function public(int $page,int $perPage):array{return $this->page($this->rooms->listPublicWaiting(($page-1)*$perPage,$perPage),$page,$perPage,$this->rooms->countPublicWaiting());} public function privateCreatedBy(string $userId,int $page,int $perPage):array{return $this->page($this->rooms->listPrivateWaitingCreatedBy($userId,($page-1)*$perPage,$perPage),$page,$perPage,$this->rooms->countPrivateWaitingCreatedBy($userId));} private function page(array $rooms,int $page,int $per,int $total):array{return ["items"=>array_map(fn($room)=>$this->mapper->map($room),$rooms),"page"=>$page,"perPage"=>$per,"total"=>$total];} }
